public final class SecurityFilter implements Filter {
    @Override
    public void doFilter(ServletRequest req, ServletResponse res, FilterChain chain)
            throws IOException, ServletException {
        if (!authenticate(req) || !authorize(req)) { deny(res); return; }
        audit(req);
        chain.doFilter(req, res);   // the action is only reached here
    }
}

public abstract class SecureAction extends ActionSupport {
    @Override
    public final String execute() throws Exception {
        if (!authenticated()) return LOGIN;     // shared sequence
        if (!authorized())    return "forbidden";
        audit();
        return doExecute();                     // business step
    }
    protected abstract String doExecute() throws Exception;
}
